/* The body of the replay the lean test runs: the page's rule modules (M, B, TR, ACT, ED, V, VW, EV, LV, SC, QR) are in scope,
   D = {nv, def, ui, hooks} is a made-up router state. It returns what the modules answer; the test compares that with the
   answers recorded when every module matched the stock page in the maintainer's comparison rig. Keep it deterministic. */
var out = {}, nv = D.nv, def = D.def, ui = D.ui, hk = D.hooks, NOW = 1795000000;
function tryit(name, f){ try { out[name] = f(); } catch (e) { out[name] = 'ERR: ' + String(e && e.message || e); } }
function pick(o, keys){ var r = {}; keys.forEach(function(k){ r[k] = o[k]; }); return r; }
function hash(m){ var h = 0, r, c; for (r = 0; r < m.length; r++) for (c = 0; c < m.length; c++) h = (h * 31 + (m[r][c] ? 1 : 0)) % 1000000007; return h; }
var L = M.parseLists(nv, def.sdn_rl), S = M.build(L, nv), env = EV.build(nv, hk, ui, 'rt', def);
env.now = function(){ return NOW * 1000; };
function members(V0, F, first){ return (VW.members(S, V0, F, env, first) || []).map(function(r){ return {mac: r.mac, ticked: !!r.ticked, offline: !!r.offline, band: r.band}; }); }
function editState(idx, change){
  var V0 = VW.open(S, idx, env), F = V0.F, o = {}, k, n = S.nets.filter(function(x){ return String(x.sdn.idx) === String(idx); })[0], sh;
  if (change) change(F, V0);
  F.crypto = VW.crypto(V0, F).value; sh = VW.shown(V0, F, env); F.shown = sh; F.shown.nodes = !!sh.cat_aimesh;
  for (k in F) if (Object.prototype.hasOwnProperty.call(F, k)) o[k] = F[k];
  o.auth = VW.authNow(V0, F); o.nodes = members(V0, F, true);
  o.expire = function(delay){ return SC.expire(NOW, F.schedDur !== undefined ? F.schedDur : SC.duration(n ? n.apg.expiretime : ''), delay); };
  return V.clean(o, idx, 'ALL');
}
tryit('lists round trip', function(){ var l = M.lists(S); return ['sdn_rl', 'vlan_rl', 'subnet_rl', 'radius_list', 'sdn_access_rl'].map(function(k){ return [k, l[k] === String(nv[k] || '')]; }); });
tryit('networks', function(){ return S.nets.map(function(n){ return [n.sdn.idx, n.sdn.sdn_name, n.apg.ssid, M.prefixOf(n) + n.apg.apg_idx]; }); });
tryit('installation', function(){ return pick(env, ['old', 'rt', 'max', 'bandMax', 'mloMax', 'bandOpts', 'mlo', 'wifi7', 'cfgReady', 'mloAll', 'mloSdn']); });
tryit('installation on the older line', function(){ var a = JSON.parse(JSON.stringify(nv)); a.buildno = '102.8'; var e = EV.build(a, hk, ui, 'rt', def); return [e.old, VW.bandOptions(e)]; });
tryit('band choices', function(){ return VW.bandOptions(env); });
tryit('detail views', function(){ return S.nets.map(function(n){ var v = VW.open(S, n.sdn.idx, env), sh = VW.shown(v, v.F, env); return [n.sdn.idx, v.kind, v.tabs, Object.keys(v.has).sort().join(' '), Object.keys(sh).filter(function(k){ return !sh[k]; }).sort().join(' ')]; }); });
tryit('wizards', function(){ return ['Guest', 'Kids', 'IoT', 'VPN', 'Customized', 'Portal', 'MLO', 'MAINFH'].map(function(k){ var w = VW.wizard(k, S, env); return [k, w ? Object.keys(w.has).sort().join(' ') : null]; }); });
tryit('list', function(){ return LV.list(S, env, {wifi7: {}, sched: {}, clients: {}, now: NOW}).map(function(r){ return r.card ? ['card', r.card.idx, r.card.kind, r.card.name, r.card.sw] : Object.keys(r).map(function(k){ return k + ':' + r[k]; }); }); });
tryit('switch a network off', function(){ var n = S.nets.filter(function(x){ return x.sdn.sdn_name === 'Guest'; })[0], r = ACT.toggle(S, n.sdn.idx, false, {qos_enable: env.qos_enable, mld_enable: env.mld_enable, trunk: env.trunk, ledg: false, cpTypes: env.cpTypes, reboot: 90, mlo: env.mlo}); return [r.post, r.wait]; });
tryit('delete a network', function(){ var n = S.nets.filter(function(x){ return x.sdn.sdn_name === 'Guest'; })[0], r = ACT.remove(S, n.sdn.idx, {qos_enable: env.qos_enable, trunk: env.trunk, ledg: false, reboot: 90}); return [r.post, r.wait]; });
tryit('delete the only main network', function(){ var n = S.nets.filter(function(x){ return x.sdn.sdn_name === 'MAINFH'; }), r = ACT.remove(S, n[0].sdn.idx, {qos_enable: env.qos_enable, trunk: env.trunk, ledg: false, reboot: 90}); return r.refuse || Object.keys(r.post).length; });
tryit('edit: rename a guest network', function(){ var n = S.nets.filter(function(x){ return x.sdn.sdn_name === 'Guest'; })[0], F = editState(n.sdn.idx, function(F){ F.ssid = 'Visitors 2'; }), e = V.check(S, n.sdn.idx, 'ALL', F, env), r = ED.edit(S, n.sdn.idx, F, env); return [e, r && r.post, r && r.wait]; });
tryit('edit: a VLAN ID out of range is refused', function(){ var n = S.nets.filter(function(x){ return x.sdn.sdn_name === 'Guest'; })[0], F = editState(n.sdn.idx, function(F){ F.vid = '9999'; }), e = V.check(S, n.sdn.idx, 'ALL', F, env); return e && e.field; });
tryit('edit: a name already in use is refused', function(){ var g = S.nets.filter(function(x){ return x.sdn.sdn_name === 'Guest'; })[0], o = S.nets.filter(function(x){ return x.sdn.idx !== g.sdn.idx && x.apg.ssid; })[0], F = editState(g.sdn.idx, function(F){ F.ssid = o.apg.ssid; }), e = V.check(S, g.sdn.idx, 'ALL', F, env); return e && e.field; });
tryit('create: a guest network', function(){
  var W = VW.wizard('Guest', S, env), F = W.F, o = {}, k, e, r;
  F.ssid = 'Front Desk'; F.sec = 'pwd'; F.pwd = 'frontdesk-2468';
  F.shown = {}; for (k in W.has) F.shown[k] = true; F.shown.nodes = true;
  for (k in F) if (Object.prototype.hasOwnProperty.call(F, k)) o[k] = F[k];
  o.nodes = (VW.wizardMembers(S, W, F, env) || []).map(function(r){ return {mac: r.mac, ticked: !!r.ticked, offline: !!r.offline, band: r.band}; });
  o.expire = function(delay){ return SC.expire(NOW, SC.DEFAULT, delay); };
  o = V.clean(o, null, 'Guest'); e = V.check(S, null, 'Guest', o, env); r = ED.create(S, 'Guest', o, env);
  return [e, r && r.post, r && r.wait, r && r.idx];
});
tryit('schedule texts', function(){ return [SC.format(SC.parse('M13E17002100<M14116002200')), SC.expire(NOW, SC.DEFAULT, 30), SC.left('T1' + (NOW - 70) + 'Z,T0' + (NOW + 7130) + 'Z', NOW), SC.left('T1' + (NOW - 9000) + 'Z,T0' + (NOW - 1800) + 'Z', NOW), SC.duration('T1' + NOW + 'Z,T0' + (NOW + 3600) + 'Z'), SC.DEFAULT, SC.MAX]; });
tryit('Wi-Fi share text and code', function(){ var t = [QR.wifi('HomeNet', 'mainkey123', false, false), QR.wifi('Cafe "Wi-Fi";:\\', 'p;a:s,s\\', false, true), QR.wifi('Open Net', '', true, false)]; return t.map(function(x){ var m = QR.matrix(x); return [x, m.length, hash(m)]; }); });
tryit('band bits', function(){ return [B.main('87'), B.main('3', true), B.main('3', false), B.parse('<AA:BB:CC:00:00:01>3><AA:BB:CC:00:00:02>16>').map(function(r){ return [r.mac, r.wifiband]; })]; });
return out;
